 for a,b in [('B.Tech, Technology Management and Mechanical Engineering','Copenhagen School of Marine and Technical Engineering · 2017–2022'),('Elautoriseret maskinmester, LV/MV/HV','Sikkerhedsstyrelsen · 2023'),('PRINCE2 certificeret projektleder','AXELOS / PeopleCert'),('El- og maskinteknisk design, elteknik','Tehran Technical University · EQF 6 · 2000–2003')]:m.edu(a,b)
 m.para('**Ingeniørværktøjer:** AutoCAD, SEE og EPLAN; konkrete anvendelser ikke specificeret. **Metoder:** Lean og Six Sigma anvendt i praksis, ikke certificeret; PRINCE2 certificeret. **Sprog:** dansk, engelsk og persisk.',after=20)
 rows=[('MV- og HV-kabler samt kabelsystemer','Erfaring med opslagets samtlige tekniske fagområder er bekræftet; konkrete kabeltyper, projekter og opgaver ikke specificeret. Vil afklare grænseflader og krav med kunden.'),('Transformere og koblingsanlæg','Erfaring med transformere, koblingsanlæg og koblingsudstyr er bekræftet; anlæg og ansvarsomfang er ikke angivet. Vil gennemgå projektspecifikationer med teamet.'),('Beskyttelsesrelæer og beskyttelsessystemer','Erfaring er bekræftet uden specifikke relætyper, indstillinger eller projekter. Vil afstemme krav og review med relevante beskyttelsesspecialister.'),('RTU, SCADA og kommunikation','Erfaring med RTU-, SCADA- og kommunikationssystemer er bekræftet; konkrete produkter og protokoller ikke oplyst. BIOFOS: SCADA og teknisk drift.'),('Jording, potentialudligning og lynbeskyttelse','Erfaring med jordings- og potentialudligningssystemer samt overspændings- og lynbeskyttelse er bekræftet; konkrete beregninger og opgaver ikke specificeret.'),('Stationsdesign og systemintegration','Erfaring med anlægsdesign af hele eller dele af MV/HV-stationer er bekræftet generelt. Projekter, designansvar og specifikke komponenter er ikke angivet.'),('Koncept, tekniske krav og Owner’s Engineer','Direkte relevant erfaring inden for Owner’s Engineer eller eBoP er bekræftet, men rolle og energitype er ikke afklaret. Vil dokumentere krav og designvalg med kunden.'),('Test, validering og teknisk review','Novo: FAT/SAT og IQ/OQ/PQ med nul kritiske afvigelser ved aflevering. Vil planlægge test og gennemgå tekniske krav og afvigelser på det konkrete anlæg.'),('Budget, ressourcer og projektgennemførelse','Novo: koordinerede 25 specialister på 37 CAPEX-projekter og fulgte økonomi og risiko; ELOHVAC: fuldt P&L. Vil følge ressourcer og leverancer.'),('Kundedialog, faglig sparring og samarbejde','ELOHVAC: kundekontakt og oplæring af tre lærlinge; Novo: tværfaglig koordinering. Vil afstemme valg med kunden og dele tekniske vurderinger med kolleger.'),('Ingeniørværktøjer og praktisk erfaring','AutoCAD, SEE og EPLAN er bekræftet; specifikke opgaver ikke angivet. El- og mekanisk drift, installation og fejlfinding fra ELOHVAC og BIOFOS.'),('Teknisk uddannelse, erfaring og sprog','Elteknisk designuddannelse, B.Tech og elautoriseret maskinmester. Mere end fem års direkte HV-erfaring er bekræftet; dansk og engelsk samt persisk.')]
 m.models_table('ROLLEBEHOV — ERFARING OG TILGANG',('Krav i rollen','Erfaring eller foreslået tilgang'),rows,widths=(2600,7746))
 m.section('FØRSTE SKRIDT I ET PROJEKT')
 for s in ['Afklar krav, kundeprioriteter, tilslutning og grænseflader med projektets deltagere.','Aftal designvalg, ressourcer og reviewpunkter med ansvarlige specialister og kunden.','Planlæg test og dokumentation; følg afvigelser til lukning og del læring i Power Engineering-teamet.']:m.bullet('',s,after=10)
